using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;
using System.Text;

[Generator(LanguageNames.CSharp)]
public class HelloWorldGenerator : IIncrementalGenerator
{
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(ctx =>
        {
            ctx.AddSource("GeneratedHello.g.cs", SourceText.From(
                "namespace GeneratedCode { public static class Hello { public static string SayHello() => \"Hello from a source generator!\"; } }",
                Encoding.UTF8));
        });
    }
}

// This code is written by you
class Program
{
    static void Main()
    {
        Console.WriteLine(GeneratedCode.Hello.SayHello());
    }
}
